    Hub public hub;

    constructor(address hubAddress) {
        if (hubAddress == address(0)) {
            revert HubLib.ZeroAddressHub();
        }

        hub = Hub(hubAddress);
    }

    modifier onlyHub() {
        _checkHub();
        _;
